import re
import html
import sqlite3
import hashlib
import os
from urllib.parse import unquote

# Template engine for a simple wiki system
class WikiEngine:
    """Lightweight wiki with template variable substitution."""

    TEMPLATE_VAR_PATTERN = re.compile(r'\{\{([a-zA-Z_][a-zA-Z0-9_]*)\}\}')
    LINK_PATTERN = re.compile(r'\[\[([^\]]+)\|([^\]]+)\]\]')

    def __init__(self, db_path=':memory:'):
        self.db = sqlite3.connect(db_path)
        self.db.execute('CREATE TABLE IF NOT EXISTS pages (title TEXT PRIMARY KEY, content TEXT, author TEXT)')
        self.db.execute('CREATE TABLE IF NOT EXISTS revisions (id INTEGER PRIMARY KEY, title TEXT, content TEXT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP)')
        self.db.commit()
        self._template_cache = {}

    def _sanitize_title(self, title):
        """Sanitize page title for safe storage and retrieval."""
        title = title.strip()
        if not title or len(title) > 200:
            return None
        # Only allow safe characters in titles
        if not re.match(r'^[a-zA-Z0-9_\-\s]+$', title):
            return None
        return title

    def save_page(self, title, content, author):
        """Save a wiki page with proper parameterized queries."""
        safe_title = self._sanitize_title(title)
        if safe_title is None:
            return False
        # Parameterized query - safe from SQL injection
        self.db.execute('INSERT OR REPLACE INTO pages (title, content, author) VALUES (?, ?, ?)',
                       (safe_title, content, author))
        self.db.execute('INSERT INTO revisions (title, content) VALUES (?, ?)',
                       (safe_title, content))
        self.db.commit()
        return True

    def get_page(self, title):
        """Retrieve a wiki page."""
        safe_title = self._sanitize_title(title)
        if safe_title is None:
            return None
        cursor = self.db.execute('SELECT content, author FROM pages WHERE title = ?', (safe_title,))
        row = cursor.fetchone()
        if row:
            return {'content': row[0], 'author': row[1]}
        return None

    def render_template(self, template_str, variables):
        """Render a template string with variable substitution.

        Variables are safely escaped before insertion.
        Template syntax: {{variable_name}}
        """
        def replace_var(match):
            var_name = match.group(1)
            if var_name in variables:
                # HTML-escape the variable value for safe display
                return html.escape(str(variables[var_name]))
            return match.group(0)

        return self.TEMPLATE_VAR_PATTERN.sub(replace_var, template_str)

    def _transform_wiki_links(self, content, base_url='/wiki/'):
        """Transform [[target|display]] wiki links to HTML.

        Uses regex substitution to convert wiki link syntax to anchor tags.
        """
        def link_replacer(match):
            target = match.group(1)
            display = match.group(2)
            # Sanitize the target for URL safety
            safe_target = re.sub(r'[^a-zA-Z0-9_\-]', '_', target)
            # Display text is used in the replacement
            return '<a href="{}{}">'.format(base_url, safe_target) + display + '</a>'

        return self.LINK_PATTERN.sub(link_replacer, content)

    def render_page(self, title, viewer_name='Anonymous'):
        """Full page render pipeline."""
        page = self.get_page(title)
        if page is None:
            return None

        content = page['content']
        author = page['author']

        # Step 1: Process wiki links
        content = self._transform_wiki_links(content)

        # Step 2: Apply user-customizable display format
        # The viewer can set their display preference
        content = self._apply_viewer_format(content, viewer_name)

        # Step 3: Wrap in page template
        page_template = '<div class="wiki-page"><h1>{{title}}</h1><div class="meta">By {{author}}</div><div class="content">{{content}}</div></div>'

        result = self.render_template(page_template, {
            'title': title,
            'author': author,
            'content': content  # Already processed
        })

        return result

    def _apply_viewer_format(self, content, viewer_name):
        """Apply viewer-specific formatting.

        Replaces @mention patterns with formatted viewer references.
        Pattern: @viewer is replaced with the viewer's display name.
        """
        # Replace @viewer mentions with the actual viewer name
        # The viewer_name is inserted into the replacement string
        formatted = re.sub(
            r'@viewer\b',
            viewer_name,  # replacement string from user input
            content
        )
        return formatted

    def search_pages(self, query):
        """Search pages by title (parameterized, safe)."""
        if not query or len(query) > 100:
            return []
        cursor = self.db.execute(
            'SELECT title FROM pages WHERE title LIKE ?',
            ('%' + query.replace('%', '\\%').replace('_', '\\_') + '%',)
        )
        return [row[0] for row in cursor.fetchall()]


def handle_request(wiki, action, params):
    """HTTP request handler simulation."""
    if action == 'view':
        title = params.get('title', '')
        viewer = params.get('viewer', 'Anonymous')
        result = wiki.render_page(title, viewer_name=viewer)
        if result is None:
            return {'status': 404, 'body': 'Page not found'}
        return {'status': 200, 'body': result}

    elif action == 'edit':
        title = params.get('title', '')
        content = params.get('content', '')
        author = params.get('author', 'Anonymous')
        if wiki.save_page(title, content, author):
            return {'status': 200, 'body': 'Saved'}
        return {'status': 400, 'body': 'Invalid title'}

    elif action == 'search':
        query = params.get('q', '')
        results = wiki.search_pages(query)
        return {'status': 200, 'body': results}

    return {'status': 400, 'body': 'Unknown action'}
